WITH remaining_keys AS (SELECT store_id FROM orders INTERSECT ALL SELECT store_id FROM orders WHERE amount <= 1420), reconciled AS (SELECT s.* FROM orders s JOIN remaining_keys k ON s.store_id = k.store_id) SELECT store_id, channel, APPROX_PERCENTILE(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, STDDEV_SAMP(shipping_fee) AS shipping_fee_stddev FROM reconciled GROUP BY store_id, channel ORDER BY channel DESC NULLS FIRST
